int N = 28;
int *ptr1 = &N;
int **ptr2 = &ptr1;

printf("%p\n", (void *)ptr2);  // dia chi cua ptr1
printf("%p\n", (void *)*ptr2); // gia tri ptr1 = dia chi N
printf("%d\n", **ptr2);        // gia tri cua N = 28

int N = 28;
int *ptr1 = &N;
int **ptr2 = &ptr1;
int ***ptr3 = &ptr2;

// *ptr3   -> gia tri cua ptr2 (dia chi cua ptr1)
// **ptr3  -> gia tri cua ptr1 (dia chi cua N)
// ***ptr3 -> gia tri cua N = 28

void change(int *x, int *y) {
    x = y;   // chi doi ban sao x, khong doi ptr1
}

change(ptr1, ptr2);
// ptr1 va ptr2 KHONG doi sau khi goi ham

void change(int **x, int *y) {
    *x = y;   // sua truc tiep gia tri cua ptr1
}

change(&ptr1, ptr2);
// ptr1 gio bang ptr2 (cung tro toi M)
